from h import *
O=[]
O.append(R(6286531,
("Salchicha de pollo salteada con pimientos","Salchicha de pollo salteada con pimientos, un plato rápido y sabroso que reúne el gusto salado de la salchicha de pollo con pimientos dulces y coloridos. Esta versión apta para personas con diabetes está llena de verduras, lo que la convierte en una comida saludable y satisfactoria.","6","1 taza",
["2 papas russet o para hornear medianas (en cubos)","2 cucharadas de aceite de oliva","1 libra de salchichas de pollo (bajas en sodio, en rodajas)","1 cebolla amarilla mediana (en rodajas finas)","4 pimientos morrones medianos (en tiras finas)","5 dientes de ajo (picados)","2 cucharaditas de orégano seco","2 cucharaditas de albahaca seca","7 ramitas de tomillo fresco","1/4 de cucharadita de sal kosher","1/4 de cucharadita de pimienta negra"],
["Lleve agua a ebullición en una cacerola mediana. Agregue las papas en cubos y cocínelas durante 7 minutos. Escúrralas.","En una sartén grande, caliente el aceite de oliva a fuego medio-alto.","Agregue las salchichas de pollo en rodajas a la sartén y saltéelas hasta que se doren por todos lados, aproximadamente de 5 a 7 minutos.","Retire las salchichas de la sartén y resérvelas. Agregue a la sartén las cebollas y los pimientos en rodajas. Saltee hasta que se ablanden, unos 10 minutos.","Sazone la mezcla con el ajo picado, el orégano seco, la albahaca seca, el tomillo fresco, la sal kosher y la pimienta. Revuelva bien para combinar.","Regrese las papas y las salchichas a la sartén y saltee de 2 a 3 minutos más. Sirva caliente."],[],[]),
("نقانق الدجاج المقلية مع الفلفل الرومي","نقانق الدجاج المقلية مع الفلفل الرومي طبق سريع ولذيذ يجمع بين المذاق المالح لنقانق الدجاج والفلفل الرومي الحلو الملوّن. هذه النسخة المناسبة لمرضى السكري مليئة بالخضار، مما يجعلها وجبة صحية ومُشبعة.","6","1 كوب",
["2 حبة بطاطس راسيت أو بطاطس للخبز متوسطة (مقطعة مكعبات)","2 ملعقة كبيرة زيت زيتون","1 رطل نقانق دجاج (قليلة الصوديوم، مقطعة شرائح)","1 حبة بصل أصفر متوسطة (مقطعة شرائح رفيعة)","4 حبات فلفل رومي متوسطة (مقطعة شرائح رفيعة)","5 فص ثوم (مفروم)","2 ملعقة صغيرة أوريغانو مجفف","2 ملعقة صغيرة ريحان مجفف","7 أغصان زعتر طازج","¼ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود"],
["أحضر الماء إلى درجة الغليان في قدر متوسط. أضف مكعبات البطاطس واطهها لمدة 7 دقائق. صفِّها.","في مقلاة كبيرة، سخّن زيت الزيتون على نار متوسطة إلى عالية.","أضف شرائح نقانق الدجاج إلى المقلاة وقلّبها حتى تحمرّ من جميع الجوانب، نحو 5 إلى 7 دقائق.","أخرج النقانق من المقلاة وضعها جانبًا. أضف شرائح البصل والفلفل إلى المقلاة. قلّبها حتى تلين، نحو 10 دقائق.","تبّل الخليط بالثوم المفروم والأوريغانو المجفف والريحان المجفف والزعتر الطازج وملح الكوشر والفلفل. حرّك جيدًا حتى تمتزج المكونات.","أعد البطاطس والنقانق إلى المقلاة وقلّبها 2 إلى 3 دقائق أخرى. قدّمها دافئة."],[],[])))
O.append(R(6287846,
("Ensalada de brócoli y mandarina","Crujiente, dulce y de sabor ácido, esta refrescante ensalada de brócoli y mandarina puede satisfacer varios antojos a la vez. Esta receta apta para personas con diabetes es un excelente acompañamiento para la cena o un almuerzo fresco. Pruebe combinarla con bacalao cítrico asado lentamente para una comida saludable para el corazón.","6","3/4 de taza",
["1/2 toronja mediana (el jugo)","1 chalote pequeño (en cubos pequeños)","1/4 de taza de aceite de oliva","1 cucharada de vinagre de champán","2 cucharaditas de miel","1/4 de cucharadita de sal","1/8 de cucharadita de pimienta","4 tazas de brócoli (cortado en floretes pequeños)","15 onzas de mandarinas enlatadas, sin azúcar añadida (escurridas)","1/4 de taza de nueces pecanas tostadas (picadas)"],
["En un tazón grande, bata el jugo de toronja, el chalote, el aceite de oliva, el vinagre, la miel, la sal y la pimienta.","Agregue el brócoli y las mandarinas; mezcle con suavidad para no romper las mandarinas. Espolvoree con las nueces pecanas."],[],[]),
("سلطة البروكلي واليوسفي","مقرمشة وحلوة ولاذعة، هذه السلطة المنعشة من البروكلي واليوسفي قادرة على تلبية عدة رغبات غذائية في آن واحد. هذه الوصفة المناسبة لمرضى السكري طبق جانبي رائع للعشاء أو غداء منعش. جرّب تقديمها مع سمك القد المحمّر ببطء بالحمضيات لوجبة صحية للقلب.","6","¾ كوب",
["½ حبة جريب فروت متوسطة (معصورة)","1 حبة كراث أخضر (شالوت) صغيرة (مقطعة مكعبات صغيرة)","¼ كوب زيت زيتون","1 ملعقة كبيرة خل الشمبانيا","2 ملعقة صغيرة عسل","¼ ملعقة صغيرة ملح","⅛ ملعقة صغيرة فلفل","4 كوب بروكلي (مقطع إلى زهيرات صغيرة)","15 أونصة يوسفي معلب بدون سكر مضاف (مصفى)","¼ كوب بيكان محمّص (مفروم)"],
["في وعاء كبير، اخفق عصير الجريب فروت والكراث الأخضر وزيت الزيتون والخل والعسل والملح والفلفل.","أضف البروكلي واليوسفي وقلّب برفق حتى لا تتفتت حبات اليوسفي. رشّ البيكان فوقها."],[],[])))
O.append(R(6288136,
("Pescado en sartén con tomates a la española","Los filetes delgados de pescado, como la tilapia o el lenguado, se cocinan muy rápido, por lo que son una excelente opción para una comida rápida entre semana. Este pescado ligero toma los sabores dulces y salados de esta salsa de tomate y aceitunas. ¡Sirva con un trozo de pan crujiente para empapar todos los jugos!","4","3 onzas de pescado cocido + 1/2 taza de mezcla de tomate",
["1 cucharada de aceite de oliva extra virgen (dividida)","4 filetes de tilapia o de cualquier otro pescado blanco magro (enjuagados y secados con toallas de papel)","1 lata (14.5 onzas) de tomates en cubos enlatados (sin sal añadida)","1/2 taza de pimiento morrón verde (en cubos)","1/2 taza de aceitunas verdes rellenas de pimiento (unas 12 aceitunas, picadas en trozos grandes)","1/2 cucharadita de orégano fresco","1/8 de cucharadita de sal"],
["Caliente 1 cucharadita de aceite en una sartén antiadherente grande a fuego medio-alto. Cocine el pescado 5 minutos por cada lado o hasta que se desmenuce con un tenedor. Resérvelo en un plato aparte.","Agregue los demás ingredientes a la sartén, reduzca el fuego a medio, tape y cocine 5 minutos o hasta que espese ligeramente. Sirva con una cuchara sobre el pescado. Si lo desea, sirva en tazones poco profundos."],[],[]),
("سمك في المقلاة مع الطماطم على الطريقة الإسبانية","شرائح السمك الرقيقة مثل البلطي أو سمك موسى (الفلاوندر) تُطهى بسرعة كبيرة، مما يجعلها خيارًا ممتازًا لوجبة سريعة في أيام الأسبوع. يكتسب هذا السمك الخفيف النكهات الحلوة والمالحة من صلصة الطماطم والزيتون هذه. قدّمه مع قطعة خبز مقرمش لامتصاص كل العصارة!","4","3 أونصات سمك مطبوخ + ½ كوب خليط الطماطم",
["1 ملعقة كبيرة زيت زيتون بكر ممتاز (يُستخدم على دفعات)","4 شرائح سمك بلطي أو أي شرائح سمك أبيض قليل الدهن (مغسولة ومجففة بالتربيت)","1 علبة (14.5 أونصة) طماطم معلبة مقطعة مكعبات (بدون ملح مضاف)","½ كوب فلفل رومي أخضر (مقطع مكعبات)","½ كوب زيتون أخضر محشو بالفلفل الحلو (نحو 12 حبة زيتون، مفروم خشنًا)","½ ملعقة صغيرة أوريغانو طازج","⅛ ملعقة صغيرة ملح"],
["سخّن 1 ملعقة صغيرة من الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. اطهُ السمك 5 دقائق على كل جانب أو حتى يتفتت بالشوكة. ضعه جانبًا في طبق منفصل.","أضف المكونات المتبقية إلى المقلاة، وخفّض النار إلى متوسطة، وغطِّ المقلاة واطهِ 5 دقائق أو حتى يثخن الخليط قليلًا. اغرفه فوق السمك. قدّمه في أطباق غير عميقة، إن رغبت."],[],[])))
O.append(R(6288534,None,
("سمك البلطي بالقشدة الحامضة والكبر","كلنا نمرّ بأمسيات مزدحمة في أيام الأسبوع، لكن لا داعي للبحث بعيدًا إن كنت بحاجة إلى وصفة عشاء سريعة. هذا طبق رائع من المأكولات البحرية يمكن تحضيره في أقل من 15 دقيقة! قدّمه مع خضار مطهوة على البخار وأرز بني لوجبة سريعة ومتوازنة.","4","1 شريحة مع 1 ملعقة كبيرة قشدة حامضة",
["1 ملعقة كبيرة كبر (مصفى)","¼ كوب قشدة حامضة (قليلة الدسم)","¼ ملعقة صغيرة ملح (يُستخدم على دفعات)","1 رطل سمك بلطي (مغسول ومجفف بالتربيت، مقسّم إلى 4 حصص)","1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","¼ ملعقة صغيرة فلفل أسود","1 حبة ليمون متوسطة (مقطعة أرباعًا)"],
["اهرس الكبر بالشوكة أو بظهر الملعقة. حرّك الكبر و⅛ ملعقة صغيرة من الملح في القشدة الحامضة.","ضع مقلاة كبيرة غير لاصقة على نار متوسطة حتى تسخن. ارشش المقلاة ببخاخ الطهي. رشّ أحد جانبي كل شريحة بالتساوي بالفلفل الأسود و⅛ ملعقة صغيرة من الملح. اطهُ 3 دقائق، ثم اقلب الشرائح واطهُ 2 إلى 3 دقائق أخرى أو حتى يصبح السمك معتمًا في الوسط.","ضع الشرائح على صحن التقديم، واعصر عصير الليمون بالتساوي فوقها جميعًا، وضع على كل شريحة 1 ملعقة كبيرة من القشدة الحامضة."],[],[])))
O.append(R(6288756,None,
("سلطة الفاصولياء اليونانية","الفاصولياء من أكثر مصادر الكربوهيدرات صحة. فهي غنية بالألياف وغيرها من العناصر الغذائية. وإذا كنت بحاجة إلى اتباع نظام غذائي خالٍ من الغلوتين، فيمكن أن تكون الفاصولياء عنصرًا أساسيًا في خطتك الغذائية.","7","½ كوب",
["1 علبة (15.5 أونصة) فاصولياء كانيليني (مشطوفة ومصفاة)","1 كوب طماطم عنبية (مقطوعة إلى نصفين)","¼ كوب بصل أحمر (مقطع مكعبات)","¼ كوب فلفل رومي أخضر (مقطع مكعبات)","¼ كوب جبن فيتا مفتت قليل الدسم","6 حبات زيتون كالاماتا كاملة (منزوعة النوى ومفرومة)","¼ كوب خل النبيذ الأحمر","¼ كوب زيت زيتون","½ ملعقة صغيرة أوريغانو مجفف","¼ ملعقة صغيرة فلفل أسود"],
["في وعاء سلطة متوسط، اخلط الفاصولياء والطماطم والبصل والفلفل الرومي وجبن الفيتا والزيتون.","في وعاء صغير، اخفق الخل وزيت الزيتون والأوريغانو والفلفل الأسود. اسكب الصلصة فوق مكونات السلطة وقلّب حتى تتغطى. قدّمها باردة."],[],[])))
O.append(R(6288870,
("Galletas saladas bajas en carbohidratos con romero y semillas de lino","Cada vez hay más opciones de galletas saladas bajas en carbohidratos en las tiendas, pero ¿por qué no probar a prepararlas usted mismo? Estas galletas saladas se hacen con romero y queso parmesano. Las semillas de chía y de lino aportan una gran cantidad de fibra y ácidos grasos omega-3. ¡El resultado son galletas crujientes con solo 4 gramos de carbohidratos y 3 gramos de fibra por porción!","12","6 galletas",
["2 rociadas, 0.5 gramos de aceite de aguacate en aerosol para cocinar","3/4 de taza de semillas de lino molidas","1/4 de taza de semillas de chía","1/3 de taza de queso parmesano (rallado fino)","2 cucharaditas de romero seco","1/2 taza de agua","1 huevo grande"],
["Precaliente el horno a 400°F. Forre dos bandejas para hornear con papel pergamino. Rocíe con el aceite de aguacate en aerosol.","En un tazón grande, mezcle el lino molido, las semillas de chía, el queso y el romero. Agregue el huevo y el agua y mezcle bien.","Tome porciones de masa del tamaño de una cucharadita y forme bolitas. Coloque las bolitas en la bandeja preparada, dejando suficiente espacio para que se extiendan y formen galletas. Cubra con otra capa de papel pergamino. Presione con las manos para aplanarlas hasta formar galletas redondas.","Hornee durante 6 minutos. Voltee y hornee otros 2 minutos o hasta que estén doradas.","Deje enfriar por completo antes de comer. Guarde en un recipiente hermético hasta por 10 días."],[],[]),
("مقرمشات الكتان بإكليل الجبل منخفضة الكربوهيدرات","يتزايد عدد خيارات المقرمشات منخفضة الكربوهيدرات في المتاجر، فلماذا لا تجرّب تحضيرها بنفسك؟ تُحضَّر هذه المقرمشات المالحة بإكليل الجبل وجبن البارميزان. وتوفر بذور الشيا وبذور الكتان كمية كبيرة من الألياف وأحماض أوميغا-3 الدهنية. والنتيجة مقرمشات هشّة تحتوي على 4 غرامات فقط من الكربوهيدرات و3 غرامات من الألياف لكل حصة!","12","6 مقرمشات",
["2 بخّة، 0.5 غرام بخاخ زيت الأفوكادو للطهي","¾ كوب بذور الكتان المطحونة","¼ كوب بذور الشيا","⅓ كوب جبن بارميزان (مبشور ناعمًا)","2 ملعقة صغيرة إكليل الجبل المجفف","½ كوب ماء","1 بيضة كبيرة"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200° مئوية). بطّن صينيتي خبز بورق الزبدة. ارششهما ببخاخ زيت الأفوكادو للطهي.","في وعاء كبير، اخلط الكتان المطحون وبذور الشيا والجبن وإكليل الجبل. أضف البيضة والماء وامزج جيدًا.","خذ كميات من العجين بحجم ملعقة صغيرة وشكّلها على هيئة كرات. ضع الكرات على الصينية المجهّزة مع ترك مسافة كافية لتنتشر وتصبح مقرمشات. غطِّها بطبقة أخرى من ورق الزبدة. اضغط عليها بيديك لتسطيحها إلى مقرمشات مستديرة.","اخبزها لمدة 6 دقائق. اقلبها واخبزها دقيقتين أخريين أو حتى تصبح ذهبية اللون.","اتركها تبرد تمامًا قبل تناولها. احفظها في وعاء محكم الإغلاق لمدة تصل إلى 10 أيام."],[],[])))
O.append(R(6289021,
("Zanahorias baby frescas","Información nutricional de las zanahorias baby frescas","1","9 zanahorias baby",["9 zanahorias baby frescas medianas"],[],[],[]),
("جزر صغير طازج (بيبي)","المعلومات الغذائية للجزر الصغير الطازج","1","9 حبات جزر صغير",["9 حبات جزر صغير طازج متوسط الحجم"],[],[],[])))
O.append(R(6289072,None,
("إمبانادا الدجاج المخبوزة","إمبانادا الدجاج ممتعة في التحضير وهي مقبّل رائع لا يحتاج إلى شوكة. يمنح خبز هذه الحلوى اللذيذة قشرة مقرمشة بدهون أقل، كما تضيف زيتونات مانزانيلا نكهة لذيذة تشبه المكسرات.","16","1 إمبانادا",
["8 أونصات صدور دجاج (بدون عظم وبدون جلد)","4 كوب مرق دجاج قليل الصوديوم (خالٍ من الدهون، قليل الصوديوم)","1 ملعقة كبيرة زيت نباتي","1 حبة بصل أصفر متوسطة (مقطعة مكعبات صغيرة)","1 ملعقة كبيرة بابريكا","1 ملعقة صغيرة كمون","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","1 رطل عجينة بيتزا جاهزة من القمح الكامل (مذابة، إذا كانت مجمدة)","16 حبة زيتون أخضر إسباني (مثل مانزانيلا، منزوعة النوى)","1 بيضة كبيرة","1 ملعقة كبيرة ماء"],
["ضع صدور الدجاج ومرق الدجاج في قدر كبير على نار عالية. أحضرها إلى درجة الغليان، ثم خفّض النار واتركها على نار هادئة لمدة 15 إلى 20 دقيقة، حتى ينضج الدجاج تمامًا. ارفع القدر عن النار واترك الدجاج يبرد في المرق حتى يصبح فاترًا عند لمسه (نحو 20 دقيقة).","فتّت الدجاج إلى قطع صغيرة واخلطه مع 2 ملعقة كبيرة من مرق الدجاج الموجود في القدر؛ ثم ضعه جانبًا.","ضع الزيت في مقلاة قلي على نار متوسطة. أضف البصل والبابريكا والكمون ومسحوق الفلفل الحار و½ كوب من مرق الدجاج. خفّض النار إلى هادئة واطهِ لمدة 10 إلى 15 دقيقة، حتى يلين البصل ويصبح شفافًا ويتبخر السائل. أضف الدجاج وحرّك للحصول على 2 كوب من الحشوة.","سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200° مئوية). ارشش صينية خبز كبيرة ببخاخ الطهي.","قسّم عجينة البيتزا من القمح الكامل إلى 16 قطعة بحجم كرة الغولف، وشكّل كل قطعة على هيئة كرة ملساء.","باستخدام النشابة، افرد كل كرة عجين على هيئة دائرة قطرها 6 بوصات.","ضع 2 ملعقة كبيرة من الحشوة في وسط الدائرة وادفع 1 حبة زيتون في وسط الحشوة. ادهن بالماء برفق الحافة السفلية للعجين على امتداد نصف الدائرة. اطوِ النصف العلوي من العجين فوق الحشوة لتشكيل نصف دائرة، واضغط الحواف معًا بإحكام. اضغط الحواف بالشوكة لإغلاق الحشوة. ضع الإمبانادا على صينية الخبز.","اخفق البيضة برفق مع 1 ملعقة كبيرة من الماء وادهن طبقة رقيقة من الخليط على السطح العلوي لكل إمبانادا.","اخبز الإمبانادا لمدة 20 دقيقة، حتى تحمرّ قليلًا."],[],[])))
O.append(R(6291531,
("Shakshuka rápida","Esta shakshuka rápida es una comida sabrosa y fácil de huevos cocinados suavemente en una salsa de tomate con especias sencillas. Está llena de sabor y es perfecta para el desayuno, el almuerzo o la cena; ideal cuando necesita algo caliente y satisfactorio en menos tiempo.","4","1 huevo + 1/2 taza de salsa + 1 rebanada de pan tostado",
["4 rebanadas de pan integral (tostadas)","1/2 taza de albahaca fresca","4 huevos grandes","1/8 de cucharadita de pimienta negra","1/4 de cucharadita de pimienta de cayena","2 tazas de salsa marinara (reducida en sodio)","2 dientes de ajo (picados)","1 pimiento morrón rojo mediano (picado)","1 cebolla mediana (picada)","1 cucharada de aceite de oliva"],
["En una sartén grande, caliente el aceite a fuego medio. Agregue la cebolla y el pimiento rojo y saltee de 6 a 7 minutos, hasta que se ablanden. Agregue el ajo y saltee 1 minuto.","Agregue la salsa marinara, la pimienta de cayena y la pimienta negra. Baje el fuego y cocine a fuego lento durante 10 minutos.","Con el dorso de una cuchara, haga 4 huecos separados entre sí en la salsa. Rompa con cuidado un huevo en cada hueco. Tape la sartén y deje que los huevos se cocinen hasta que cuajen pero sigan suaves, unos 10 a 12 minutos. Espolvoree las hojas de albahaca sobre la mezcla en la sartén, tape y cocine 1 minuto. Los huevos deben estar cuajados, no líquidos.","Para servir, coloque con una cuchara 1 huevo y 1/2 taza de salsa sobre cada rebanada de pan tostado."],[],[]),
("شكشوكة سريعة","هذه الشكشوكة السريعة وجبة سريعة ولذيذة من البيض المطهو بلطف في صلصة طماطم شهية بتوابل بسيطة. إنها مليئة بالنكهة ومثالية للفطور أو الغداء أو العشاء، وهي رائعة عندما تحتاج إلى شيء دافئ ومُشبع في وقت أقل.","4","1 بيضة + ½ كوب صلصة + 1 شريحة خبز محمّص",
["4 شرائح خبز قمح كامل (محمّصة)","½ كوب ريحان طازج","4 بيضات كبيرة","⅛ ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة فلفل كايين","2 كوب صلصة مارينارا (منخفضة الصوديوم)","2 فص ثوم (مفروم)","1 حبة فلفل رومي أحمر متوسطة (مقطعة)","1 حبة بصل متوسطة (مقطعة)","1 ملعقة كبيرة زيت زيتون"],
["في مقلاة كبيرة، سخّن الزيت على نار متوسطة. أضف البصل والفلفل الأحمر وقلّبهما لمدة 6 إلى 7 دقائق، حتى يلينا. أضف الثوم وقلّب لمدة 1 دقيقة.","أضف صلصة المارينارا وفلفل الكايين والفلفل الأسود. اخفض النار إلى هادئة واتركها تغلي بهدوء لمدة 10 دقائق.","باستخدام ظهر الملعقة، اصنع 4 حفر متباعدة في الصلصة. اكسر بيضة بلطف في كل حفرة. غطِّ المقلاة واترك البيض ينضج حتى يتماسك لكنه يبقى طريًا، نحو 10 إلى 12 دقيقة. رشّ أوراق الريحان فوق الخليط في المقلاة، وغطِّها واطهِ لمدة 1 دقيقة. يجب أن يكون البيض متماسكًا لا سائلًا.","للتقديم، ضع 1 بيضة و½ كوب من الصلصة بالملعقة فوق كل شريحة خبز محمّص."],[],[])))
O.append(R(6292540,
("Pechuga de pollo cocida, 6 onzas","Información nutricional de la pechuga de pollo cocida, 6 onzas","1","6 onzas",["6 onzas de pechuga de pollo (sin piel, cocida)"],[],[],[]),
("صدر دجاج مطبوخ، 6 أونصات","المعلومات الغذائية لصدر الدجاج المطبوخ، 6 أونصات","1","6 أونصات",["6 أونصات صدر دجاج (بدون جلد، مطبوخ)"],[],[],[])))
O.append(R(6293155,
("Pollo al limón con hierbas, verduras y arroz integral en una sola bandeja","Disfrute de una comida completa con menos que limpiar. Esta sencilla receta en bandeja combina pollo tierno al limón con hierbas, verduras de colores y arroz integral sustancioso para una cena equilibrada y llena de sabor, perfecta para las noches ajetreadas entre semana.","4","1/4 de la bandeja",
["2 cucharadas de aceite de oliva","2 cucharadas de jugo de limón","1 cucharadita de orégano seco","1 cucharadita de tomillo seco","1/2 cucharadita de ajo en polvo","1/8 de cucharadita de sal","1/8 de cucharadita de pimienta","4 pechugas de pollo enteras, deshuesadas y sin piel","2 tazas de brócoli (floretes)","2 tazas de pimientos morrones (de varios colores, cortados en tiras)","1 taza de tomates cherry","1 calabacín mediano (en rodajas)","2 tazas de arroz integral (cocido)","1 1/2 cucharadas de perejil fresco (picado, para decorar)"],
["Precaliente el horno a 400 grados F. Forre una bandeja grande para hornear con papel pergamino o papel de aluminio para facilitar la limpieza.","Prepare el adobo mezclando el aceite de oliva, el jugo de limón, el orégano, el tomillo, el ajo en polvo, la sal y la pimienta en un tazón pequeño.","Acomode las pechugas de pollo de un lado de la bandeja. Úntelas generosamente con el adobo de limón y hierbas.","Mezcle las verduras (brócoli, pimientos morrones, tomates cherry y calabacín) con el adobo restante. Acomódelas del otro lado de la bandeja, alrededor del pollo.","Hornee de 25 a 30 minutos o hasta que el pollo alcance una temperatura interna de 165 grados F y las verduras estén tiernas.","Para servir, divida el pollo y las verduras, y agregue 1/2 taza de arroz integral cocido a cada plato o tazón. Cubra con perejil recién picado."],[],[]),
("دجاج بالليمون والأعشاب مع الخضار والأرز البني في صينية واحدة","استمتع بوجبة متكاملة مع تنظيف أقل. تجمع وصفة الصينية السهلة هذه بين دجاج طري بالليمون والأعشاب وخضار ملونة وأرز بني مشبع لعشاء متوازن ولذيذ، مثالي لأمسيات الأسبوع المزدحمة.","4","¼ الصينية",
["2 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة أوريغانو مجفف","1 ملعقة صغيرة زعتر مجفف","½ ملعقة صغيرة مسحوق الثوم","⅛ ملعقة صغيرة ملح","⅛ ملعقة صغيرة فلفل","4 صدور دجاج كاملة بدون عظم وبدون جلد","2 كوب بروكلي (زهيرات)","2 كوب فلفل رومي (بألوان متنوعة، مقطع شرائح طويلة)","1 كوب طماطم كرزية","1 حبة كوسا متوسطة (مقطعة شرائح)","2 كوب أرز بني (مطبوخ)","1½ ملعقة كبيرة بقدونس طازج (مفروم، للتزيين)"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200° مئوية). بطّن صينية خبز كبيرة بورق الزبدة أو ورق الألمنيوم لتسهيل التنظيف.","حضّر التتبيلة بخلط زيت الزيتون وعصير الليمون والأوريغانو والزعتر ومسحوق الثوم والملح والفلفل في وعاء صغير.","رتّب صدور الدجاج على أحد جانبي الصينية. ادهنها بسخاء بتتبيلة الليمون والأعشاب.","قلّب الخضار (البروكلي والفلفل الرومي والطماطم الكرزية والكوسا) في التتبيلة المتبقية. رتّبها على الجانب الآخر من الصينية حول الدجاج.","اخبزها لمدة 25 إلى 30 دقيقة أو حتى تصل درجة الحرارة الداخلية للدجاج إلى 165 درجة فهرنهايت (75° مئوية) وتصبح الخضار طرية.","للتقديم، وزّع الدجاج والخضار وأضف ½ كوب من الأرز البني المطبوخ إلى كل طبق أو وعاء. زيّنها بالبقدونس المفروم طازجًا."],[],[])))
O.append(R(6293286,None,
("سلطة الدجاج الكريمية بالتيرياكي في أكواب الخس","صلصة التيرياكي غالبًا ما تحتوي على نسبة عالية جدًا من السكر. هذه النسخة المنزلية أقل بكثير في الكربوهيدرات من الجاهزة في المتاجر. وإذا وجدت صلصة تيرياكي منخفضة الكربوهيدرات في المتجر، فيمكنك استخدامها بدلًا من تحضير الصلصة بنفسك.","6","1 كوب خس + ¾ كوب سلطة دجاج",
["3 ملعقة كبيرة صلصة صويا قليلة الصوديوم","¼ كوب ماء","1 ملعقة كبيرة عسل","1 ملعقة كبيرة بديل سكر قليل السعرات","1 فص ثوم (مبشور أو مفروم)","¼ كوب مايونيز خفيف","¼ كوب زبادي يوناني سادة خالي الدسم","1 رطل صدور دجاج بدون عظم وبدون جلد (مطبوخة ومفتتة)","2 ساق كرفس (مقطعة مكعبات)","1 حبة جزر متوسطة (مبشورة)","¼ كوب لوز شرائح (محمّص)","6 ورقات خس بيب أو بوسطن (منظفة ومجففة)"],
["في قدر صغير، اخفق صلصة الصويا والماء والعسل والثوم. أحضرها إلى درجة الغليان ثم خفّضها إلى غليان هادئ. اتركها على نار هادئة لمدة 7 إلى 8 دقائق أو حتى تتقلص الصلصة إلى ¼ كوب. ضعها جانبًا لتبرد.","بعد أن تبرد، ضع صلصة التيرياكي في وعاء كبير. أضف المايونيز والزبادي اليوناني واخفقهما جيدًا حتى تمتزجا.","أضف الدجاج والكرفس والجزر واللوز وحرّك جيدًا حتى تمتزج المكونات.","وزّع سلطة الدجاج على 6 ورقات خس بيب (¾ كوب من سلطة الدجاج لكل كوب خس)."],[],[])))
